let zoom=1,panX=0,panY=0,drag=null;const viewport=$('#map-viewport'),canvas=$('#map-canvas');
function drawMap(){const maxX=(zoom-1)*viewport.clientWidth/2,maxY=(zoom-1)*canvas.offsetHeight/2;panX=Math.max(-maxX,Math.min(maxX,panX));panY=Math.max(-maxY,Math.min(maxY,panY));canvas.style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`;viewport.classList.toggle('zoomed',zoom>1);$('#zoom-out').disabled=zoom<=1;$('#zoom-in').disabled=zoom>=2.5}
$('#zoom-in').onclick=()=>{zoom=Math.min(2.5,zoom+.5);drawMap()};$('#zoom-out').onclick=()=>{zoom=Math.max(1,zoom-.5);drawMap()};$('#map-reset').onclick=()=>{zoom=1;panX=panY=0;drawMap()};
