let filter='all',limit=3;function renderCombos(){const all=[...$('#combo-grid').children],list=all.filter(x=>filter==='all'||x.dataset.type===filter);all.forEach(x=>x.hidden=!list.includes(x)||list.indexOf(x)>=limit);$('#load').hidden=limit>=list.length}
