async function chooseTaste(key){
 const data=flavors[key];if(!data)return;const request=++tasteRequest;const frame=$('.world-window'),status=$('#taste-status');
 frame.setAttribute('aria-busy','true');status.textContent='Đang mở thế giới vị giác…';status.hidden=false;
 try{const [image,dish]=await Promise.all([preloadImage('assets/'+data.image+'.webp'),preloadImage('assets/food-'+tasteDishes[key]+'.webp')]);if(request!==tasteRequest)return;
 tasteSelected=key;$('#taste-photo').src=image.src;$('#taste-photo').alt='Phối cảnh '+data.name+' từ concept FIREBEAT';$('#taste-dish').src=dish.src;$('#taste-dish').alt='Món ăn minh họa cảm hứng '+data.name;$('#taste-photo-label').textContent=data.name.toUpperCase()+' / PHỐI CẢNH VEC';$('#taste-count').textContent='0'+(tasteKeys.indexOf(key)+1)+' / 04';$('#taste-title').textContent=data.title.replace(/<br>/g,' ');$('#taste-desc').textContent=data.desc;$('#taste-menu').textContent=data.menu;$('#taste-map').textContent='Tìm '+data.name+' trên bản đồ ↗';$('.table-top').dataset.taste=key;$$('button[data-taste]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.taste===key)));frame.setAttribute('aria-busy','false');status.hidden=true;
 }catch{if(request!==tasteRequest)return;frame.setAttribute('aria-busy','false');status.textContent='Chưa tải được ảnh. Chọn lại vùng vị để thử lần nữa.';status.hidden=false;}
}

