const lanes=$$('.food-lane').map((lane,row)=>{const items=foodItems.slice(row*3,row*3+3),track=lane.querySelector('.food-track');track.innerHTML=Array.from({length:6},(_,copy)=>items.map((food,index)=>`<a class="food-card" href="#combos" data-food="${row*3+index}" data-copy="${copy}" style="--food-bg:${food.color};--food-tilt:${index%2?2:-2}deg" ${copy?'tabindex="-1" aria-hidden="true"':''}><img src="assets/food-${food.image}.webp" alt="${food.name}, hình minh họa" loading="lazy"><small>${food.world}</small><strong>${food.name}</strong><span aria-hidden="true">↗</span></a>`).join('')).join('');const state={lane,track,phase:row?200:0,direction:row?-1:1,period:1,step:1,hover:false};lane.addEventListener('pointerenter',()=>state.hover=true);lane.addEventListener('pointerleave',()=>state.hover=false);return state;});
