function mod(n,p){return ((n%p)+p)%p;}
function drawLane(s){s.track.style.transform='translate3d('+(-mod(s.phase,s.period))+'px,0,0)';}
function finishSpin(){const choice=spin.choice,lane=lanes[choice.row];const cards=[...lane.track.querySelectorAll('[data-food="'+choice.index+'"]')];const center=lane.lane.getBoundingClientRect().left+lane.lane.clientWidth/2;const winner=cards.reduce((best,card)=>Math.abs(card.getBoundingClientRect().left+card.offsetWidth/2-center)<Math.abs(best.getBoundingClientRect().left+best.offsetWidth/2-center)?card:best,cards[0]);winner.classList.add('is-winner');$('.food-game').classList.add('has-pick');gamePicked=true;spin=null;$('#spin-food').disabled=false;$('#spin-food').innerHTML='<span aria-hidden="true">✳</span> Chọn lại món khác';$('#spin-food').setAttribute('aria-busy','false');$('#food-result').hidden=false;$('#food-result-name').textContent=foodItems[choice.index].name;$('#game-status').textContent='Chiếc bụng chọn '+foodItems[choice.index].name+'. Chọn món này để xem combo, hoặc quay lại.';$('#food-result-link').onclick=e=>{e.preventDefault();recommendCombo(foodItems[choice.index]);};}
function spinFood(){if(spin)return;measureLanes();gamePicked=false;$('.food-game').classList.remove('has-pick');$$('.food-card.is-winner').forEach(c=>c.classList.remove('is-winner'));$('#food-result').hidden=true;const index=Math.floor(Math.random()*foodItems.length),row=Math.floor(index/3);$('#spin-food').disabled=true;$('#spin-food').setAttribute('aria-busy','true');$('#game-status').textContent='Đang quay… chiếc bụng sắp có câu trả lời.';const starts=lanes.map(s=>s.phase),distances=lanes.map((s,i)=>{const selected=i===row?index%3:Math.floor(Math.random()*3);const target=mod(selected*s.step+s.track.querySelector('.food-card').offsetWidth/2-s.lane.clientWidth/2,s.period);return s.direction*(s.period*5+mod((target-mod(s.phase,s.period))*s.direction,s.period));});spin={start:performance.now(),duration:reducedMotion.matches?0:4400,starts,distances,choice:{index,row}};if(reducedMotion.matches){lanes.forEach((s,i)=>{s.phase=starts[i]+distances[i];drawLane(s);});finishSpin();}}
$('#spin-food').addEventListener('click',spinFood);
$$('.food-card').forEach(card=>{card.addEventListener('click',e=>{e.preventDefault();if(spin)return;recommendCombo(foodItems[Number(card.dataset.food)]);});card.addEventListener('focus',()=>{const s=lanes[Math.floor(Number(card.dataset.food)/3)];s.lane.style.overflowX='auto';s.track.style.transform='none';card.scrollIntoView({block:'nearest',inline:'center',behavior:'auto'});});card.addEventListener('blur',()=>{const s=lanes[Math.floor(Number(card.dataset.food)/3)];s.lane.style.overflowX='';s.lane.scrollLeft=0;});});
function frame(now){const dt=Math.min((now-lastFrame)/1000||0,.05);lastFrame=now;const focused=$('.food-reels').contains(document.activeElement);if(spin){const t=Math.min(1,(now-spin.start)/spin.duration);const ease=1-Math.pow(1-t,4);lanes.forEach((s,i)=>{s.phase=spin.starts[i]+spin.distances[i]*ease;drawLane(s);});if(t>=1)finishSpin();}else if(gameVisible&&!gamePicked&&!reducedMotion.matches&&!focused){lanes.forEach(s=>{if(!s.hover){s.phase+=s.direction*dt*26;drawLane(s);}});}requestAnimationFrame(frame);}
measureLanes();window.addEventListener('resize',()=>{measureLanes();if(gamePicked){gamePicked=false;$('.food-game').classList.remove('has-pick');$$('.food-card.is-winner').forEach(c=>c.classList.remove('is-winner'));}});if('IntersectionObserver'in window)new IntersectionObserver(entries=>gameVisible=entries[0].isIntersecting,{rootMargin:'150px'}).observe($('.food-game'));else gameVisible=true;requestAnimationFrame(frame);

// Day tabs share the concept's same unconfirmed program framework; no invented show times.
const agendaDays=['27.11.2026 — Thứ Sáu','28.11.2026 — Thứ Bảy','29.11.2026 — Chủ Nhật'];
function renderAgenda(index){$$('[data-day]').forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;});$('#agenda-panel').setAttribute('aria-labelledby','agenda-day-'+index);$('#agenda-panel').innerHTML=[['Ẩm thực','Bốn thế giới đang lên bếp.','Khám phá ẩm thực, bếp nướng và các vùng vị.','10:00–24:00 / giờ sự kiện'],['Chef Show','Đến gần người giữ lửa.','Trình diễn và câu chuyện món ăn theo concept.','Giờ diễn chờ xác nhận'],['Âm nhạc','Ngồi lại thêm một bài.','Âm nhạc, DJ và nghệ thuật trình diễn.','Lịch diễn sắp cập nhật']].map(row=>`<div class="agenda-row"><span class="agenda-category">${row[0]}</span><div><h3>${row[1]}</h3><p>${row[2]}</p></div><span>${row[3]}</span></div>`).join('')+'<p class="agenda-day-note">'+agendaDays[index]+' · Lịch khung dự kiến. Chương trình riêng từng ngày sẽ được cập nhật sau khi xác nhận.</p>';}
$$('[data-day]').forEach((tab,i)=>{tab.addEventListener('click',()=>renderAgenda(i));tab.addEventListener('keydown',e=>{const keys={ArrowRight:(i+1)%3,ArrowLeft:(i+2)%3,Home:0,End:2};if(keys[e.key]===undefined)return;e.preventDefault();renderAgenda(keys[e.key]);$$('[data-day]')[keys[e.key]].focus();});});renderAgenda(0);
['food-brand-loop','partner-brand-loop'].forEach((id,row)=>{const roles=row?['Đồng hành','Trải nghiệm','Di chuyển','Truyền thông','Đối tác','Cộng đồng']:['BBQ','Vị Á','Vị Việt','Vị Hà Nội','Đồ uống','Món ngọt'];const set=roles.map((role,i)=>`<span class="brand-slot"><i aria-hidden="true">${['✳','◉','✦','◎','✺','◌'][i]}</i><span>${role}<br>Logo sắp công bố</span></span>`).join('');$('#'+id).innerHTML='<div class="logo-track"><div style="display:flex;gap:inherit">'+set+'</div><div aria-hidden="true" style="display:flex;gap:inherit">'+set+'</div></div>';});
