const journalArticles=[{"slug": "hen-nhau-o-vec", "category": "ĐIỂM HẸN", "title": "Hẹn nhau ở VEC. Bắt đầu từ đâu?", "image": "festival.webp", "intro": "Bắt lửa. Bắt nhịp. Ba ngày để ăn có gu và gặp những người cùng nhịp tại Hà Nội."}, {"slug": "bat-lua-bat-nhip", "category": "VỊ NGON", "title": "FIREBEAT, phải biết. Ăn có gu. Quẩy có nhịp.", "image": "client-combo-cup.webp", "intro": "Bắt lửa từ BBQ. Bắt nhịp bằng âm nhạc. Và tận hưởng cuộc vui theo gu của mình."}, {"slug": "voucher-50k", "category": "VOUCHER & THANH TOÁN", "title": "Đi hội với voucher 50K. Cần biết gì?", "image": "food-ribs.webp", "intro": "Một nguyên tắc cần nhớ trước khi gọi món: sự kiện sử dụng voucher đồng giá 50.000đ và không thanh toán tiền mặt."}, {"slug": "chon-combo-hop-hoi", "category": "COMBO", "title": "Tìm Anh. Tìm Em. Tìm đúng gu mình.", "image": "set-tim-em.webp", "intro": "FIRE × FIND: từ hai set cá nhân đến một bàn tiệc cả hội. Chọn món, đồ uống và cách tận hưởng hợp gu mình."}, {"slug": "bon-the-gioi-vi-giac", "category": "VỊ NGON", "title": "Bốn thế giới vị giác. Bạn bắt đầu từ đâu?", "image": "asian.webp", "intro": "Một vòng lửa toàn cầu, một hành trình gia vị châu Á, rồi trở về những vị quen của Việt Nam và Hà Nội."}, {"slug": "mang-firebeat-ve-nha", "category": "BỘ SƯU TẬP", "title": "Mang một chút FIREBEAT về nhà.", "image": "merch-collection.webp", "intro": "Một chiếc tote, chiếc nón, áo, đôi vớ hay nam châm tủ lạnh. Những vật nhỏ để nhớ một cuộc vui lớn."}, {"slug": "chuyen-di-den-dai-tiec", "category": "DI CHUYỂN & ƯU ĐÃI", "title": "Đường đến đại tiệc. Để dành chỗ cho cuộc vui.", "image": "table.webp", "intro": "Hẹn giờ gặp, chọn cách đến và kiểm tra ưu đãi trước khi đi. Một chút chuẩn bị để chiếc bụng được thảnh thơi."}];
let journalPage=0,journalTopic='all';
const journalTopics=[['all','Tất cả'],['guide','Đi lại & Điểm hẹn'],['combo','Combo & Voucher'],['food','Thế giới vị giác'],['gift','Quà tặng']];
function topicOf(article){return article.category==='ĐIỂM HẸN'||article.category==='DI CHUYỂN & ƯU ĐÃI'?'guide':article.category==='COMBO'||article.category==='VOUCHER & THANH TOÁN'?'combo':article.category==='VỊ NGON'?'food':'gift';}
function journalCard(a,pinned=false){return `<a class="journal-item ${pinned?'journal-pin':''}" href="?bai=${a.slug}#road" data-article="${a.slug}"><span class="journal-image ${a.image.startsWith('food-')?'is-food':''}"><img src="assets/${a.image}" alt="${escapeHTML(a.title)}" loading="lazy">${pinned?'<b class="pin-label">BÀI GHIM</b>':''}</span><span class="journal-copy"><small>${a.category}</small><h3>${a.title}</h3><p>${a.intro}</p><span>Đọc câu chuyện ↗</span></span></a>`;}
function renderJournal(direction=0){const filtered=journalArticles.slice(1).filter(a=>journalTopic==='all'||topicOf(a)===journalTopic);const pages=Math.max(1,Math.ceil(filtered.length/3));journalPage=Math.max(0,Math.min(pages-1,journalPage));$('#journal-topics').innerHTML=journalTopics.map(([key,label])=>`<button data-topic="${key}" aria-pressed="${key===journalTopic}">${label}</button>`).join('');if(!$('#journal-secondary'))$('#journal-grid').innerHTML=journalCard(journalArticles[0],true)+'<div id="journal-secondary" class="journal-secondary"></div>';const secondary=$('#journal-secondary');secondary.innerHTML=filtered.slice(journalPage*3,journalPage*3+3).map(a=>journalCard(a)).join('')||'<p class="journal-empty">Các câu chuyện mới đang được chuẩn bị.</p>';secondary.style.setProperty('--journal-from',direction<0?'-30px':'30px');secondary.classList.remove('journal-arriving');if(direction){void secondary.offsetWidth;secondary.classList.add('journal-arriving');}$('#journal-pages').innerHTML=`<button data-journal-dir="-1" aria-label="Xem nhóm bài trước" aria-controls="journal-secondary" ${journalPage===0?'disabled':''}>←</button><button data-journal-dir="1" aria-label="Xem nhóm bài tiếp theo" aria-controls="journal-secondary" ${journalPage>=pages-1?'disabled':''}>→</button>`;$('#journal-status').textContent=filtered.length?'Đang xem '+(journalPage*3+1)+'–'+Math.min(filtered.length,journalPage*3+3)+' trong '+filtered.length+' câu chuyện · Bài ghim luôn ở đây.':'Chưa có bài thuộc chủ đề này. Bài ghim vẫn sẵn để bạn tham khảo.';}
$('#journal-topics').addEventListener('click',e=>{const button=e.target.closest('[data-topic]');if(!button)return;journalTopic=button.dataset.topic;journalPage=0;renderJournal(1);$('[data-topic="'+journalTopic+'"]').focus({preventScroll:true});});
$('#journal-pages').addEventListener('click',e=>{const button=e.target.closest('[data-journal-dir]');if(!button||button.disabled)return;const direction=Number(button.dataset.journalDir);journalPage+=direction;renderJournal(direction);const next=$('[data-journal-dir="'+direction+'"]');(next.disabled?$('[data-journal-dir="'+(-direction)+'"]'):next).focus({preventScroll:true});});renderJournal();
