function renderFAQ(page){const pages=Math.ceil(faqData.length/5);page=Math.max(0,Math.min(pages-1,page));$('#faq-list').innerHTML=faqData.slice(page*5,page*5+5).map((item,i)=>`<article class="faq-item"><h3><button class="faq-question" id="faq-question-${page*5+i}" aria-expanded="false" aria-controls="faq-answer-${page*5+i}"><span>${String(page*5+i+1).padStart(2,'0')} / ${item[0]}</span><b aria-hidden="true">+</b></button></h3><div id="faq-answer-${page*5+i}" class="faq-answer" role="region" aria-labelledby="faq-question-${page*5+i}" hidden><p>${item[1]}</p></div></article>`).join('');$('#faq-pages').innerHTML=Array.from({length:pages},(_,i)=>`<button data-faq-page="${i}" aria-label="Trang câu hỏi ${i+1}" ${i===page?'aria-current="page"':''}>${i+1}</button>`).join('');}
$('#faq-list').addEventListener('click',e=>{const question=e.target.closest('.faq-question');if(!question)return;const shouldOpen=question.getAttribute('aria-expanded')!=='true';$$('.faq-question').forEach(button=>{const open=button===question&&shouldOpen;button.setAttribute('aria-expanded',String(open));document.getElementById(button.getAttribute('aria-controls')).hidden=!open;});});
