// One home-page reader; the address identifies content while the home page stays underneath.
let readerRequest=0,readerDataPromise=null,readerSuppressClose=false,readerTitle=document.title;
function contentData(){if(!readerDataPromise)readerDataPromise=fetch('content-v26.json').then(response=>{if(!response.ok)throw new Error('Content unavailable');return response.json();}).catch(error=>{readerDataPromise=null;throw error;});return readerDataPromise;}
function readerRoute(){const params=new URL(location.href).searchParams;const article=params.get('bai'),policy=params.get('chinh-sach');return article?{kind:'articles',slug:article}:policy?{kind:'policies',slug:policy}:null;}
function removeReaderParams(){const url=new URL(location.href);url.searchParams.delete('bai');url.searchParams.delete('chinh-sach');return url;}
async function syncReaderRoute(){const route=readerRoute(),dialog=$('#reader-dialog');const request=++readerRequest;if(!route){if(dialog.open){readerSuppressClose=true;dialog.close();}document.body.classList.remove('content-modal-open');document.title=readerTitle;return;}document.body.classList.add('content-modal-open');if(!dialog.open)dialog.showModal();$('#reader-scroll').scrollTop=0;$('#reader-title').textContent='Đang mở nội dung…';$('#reader-category').textContent='FIREBEAT';$('#reader-intro').textContent='';$('#reader-body').innerHTML='';$('#reader-cover').hidden=true;$('#reader-status').textContent='Đang tải…';dialog.setAttribute('aria-busy','true');try{const data=await contentData();if(request!==readerRequest||!dialog.open)return;const item=data[route.kind].find(a=>a.slug===route.slug);if(!item){$('#reader-title').textContent='Nội dung chưa được tìm thấy.';$('#reader-status').textContent='Bạn có thể đóng cửa sổ và chọn một bài khác.';dialog.setAttribute('aria-busy','false');return;}$('#reader-title').textContent=item.title;$('#reader-category').textContent=item.category;$('#reader-intro').textContent=item.intro;$('#reader-body').innerHTML=item.body;if(item.image){$('#reader-cover').src='assets/'+item.image;$('#reader-cover').alt=item.title+', hình minh họa';$('#reader-cover').classList.toggle('is-food',item.image.startsWith('food-'));$('#reader-cover').hidden=false;}document.title=item.title+' — FIREBEAT';$('#reader-status').textContent='';dialog.setAttribute('aria-busy','false');}catch{if(request!==readerRequest||!dialog.open)return;$('#reader-title').textContent='Chưa tải được nội dung.';$('#reader-status').innerHTML='Kiểm tra kết nối và <button id="reader-retry">thử lại</button>.';$('#reader-retry').addEventListener('click',syncReaderRoute);dialog.setAttribute('aria-busy','false');}}
function openReader(kind,slug){const url=removeReaderParams();url.searchParams.set(kind==='articles'?'bai':'chinh-sach',slug);history.pushState({firebeatReader:true},'',url);syncReaderRoute();}
function ordinaryClick(e){return !e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey&&(e.button===0||e.button===undefined);}
$('#journal-grid').addEventListener('click',e=>{const link=e.target.closest('[data-article]');if(!link||!ordinaryClick(e))return;e.preventDefault();openReader('articles',link.dataset.article);});
$$('[data-policy]').forEach(link=>link.addEventListener('click',e=>{if(!ordinaryClick(e))return;e.preventDefault();openReader('policies',link.dataset.policy);}));
